const offers=["DEMO-001", "DEMO-002", "DEMO-003", "DEMO-004", "DEMO-005", "DEMO-006", "DEMO-007", "DEMO-008", "DEMO-009", "DEMO-010", "DEMO-011", "DEMO-012", "DEMO-013", "DEMO-014", "DEMO-015", "DEMO-016", "DEMO-017", "DEMO-018", "DEMO-019", "DEMO-020", "DEMO-021", "DEMO-022", "DEMO-023", "DEMO-024"]; // synthetic offer ids (DemoBrand); in production the list comes from the SKU master
const url='https://api-seller.ozon.ru/v5/product/info/prices';
const body={filter:{offer_id:offers,visibility:'ALL'},cursor:'',limit:100};
return [{json:{url,body,meta:{nOffers:offers.length,contract:'seller_price_snapshot_daily'}}}];

const it=$input.first();
let buf=null; try{buf=await this.helpers.getBinaryDataBuffer(0,'raw');}catch(e){buf=null;}
const status=Number(it.json?.statusCode??-1);
if(status!==200) throw new Error('OZON_PRICES_HTTP_'+status);
if(!buf||!buf.length) throw new Error('OZON_PRICES_EMPTY_BODY');
const crypto=require('crypto');
const sha=crypto.createHash('sha256').update(buf).digest('hex');
const parsed=JSON.parse(buf.toString('utf8'));
const items=parsed.items||[];
if(!items.length) throw new Error('OZON_PRICES_ZERO_ITEMS');
// business_date Europe/Moscow
const msk=new Date(Date.now()+3*60*60*1000);
const y=msk.getUTCFullYear();
const m=String(msk.getUTCMonth()+1).padStart(2,'0');
const d=String(msk.getUTCDate()).padStart(2,'0');
const businessDate=`${y}-${m}-${d}`;
const runId=`PRICE-DAILY-${y}${m}${d}`;
const capturedAt=new Date().toISOString();
const rows=[]; const rawItems=[];
for(const it of items){
  const pr=it.price||{};
  if(pr.price==null) continue;
  const pi=it.price_indexes||{};
  // Overall price index = price_indexes.color_index (the same value the seller dashboard shows).
  // value = from the sub-block whose color equals the overall color (ozon > external > self); null if none matches.
  const color=pi.color_index||null; let pival=null, pisrc=null;
  for(const key of ['ozon_index_data','external_index_data','self_marketplaces_index_data']){
    const block=pi[key]||{};
    if(color && block.price_index_color===color && block.price_index_value!=null && pival==null){ pival=block.price_index_value; pisrc=key; }
  }
  const actions=((it.marketing_actions||{}).actions)||[];
  rows.push({
    business_date:businessDate,
    offer_id:String(it.offer_id),
    product_id:it.product_id??null,
    seller_price_rub:pr.price,
    marketing_seller_price_rub:pr.marketing_seller_price??null,
    old_price_rub:pr.old_price??null,
    min_price_rub:pr.min_price??null,
    retail_price_rub:pr.retail_price??null,
    net_price_rub:pr.net_price??null,
    currency_code:pr.currency_code||'RUB',
    vat:pr.vat??null,
    auto_action_enabled:pr.auto_action_enabled??null,
    auto_add_to_ozon_actions_list_enabled:pr.auto_add_to_ozon_actions_list_enabled??null,
    ozon_actions_count:actions.length,
    price_index_color:color,
    price_index_value:pival,
    captured_at_utc:capturedAt,
    source_endpoint:'/v5/product/info/prices',
    source_workflow_id:$workflow.id,
    run_id:runId,
    response_sha256:sha,
    price_index_logic:'v5.price_indexes.color_index'+(pisrc?'; value:'+pisrc:'; value:null'),
  });
  rawItems.push({offer_id:String(it.offer_id), product_id:it.product_id??null, color_index:color, commissions:it.commissions??null, marketing_actions:it.marketing_actions??null, acquiring:it.acquiring??null, raw:it});
}
if(!rows.length) throw new Error('OZON_PRICES_NO_PARSED_ROWS');
return [{json:{business_date:businessDate,run_id:runId,n_rows:rows.length,response_sha256:sha,captured_at_utc:capturedAt,source_workflow_id:$workflow.id,rows,raw_items:rawItems}}];

const row=$input.first().json;
return [{json:{
  status:'SUCCEEDED',
  contract:'seller_price_snapshot_daily',
  business_date:row.business_date,
  run_id:row.run_id,
  n_rows_in:row.n_rows_in,
  n_inserted:row.n_inserted,
  n_raw_inserted:row.n_raw_inserted,
  note:'append-only raw.seller_price_obs; READONLY Ozon prices; no import/prices write'
}}];
